#include "field_qq.hpp"
int main(int argc,char**argv){fmpq_mpoly_ctx_init(ctx,2,ORD_LEX);{ifstream fs(argv[1]);int nf;fs>>nf;vector<Rat>f(nf);for(auto&x:f)readpoly(fs,x.n);ifstream in(argv[2]);int id;while(in>>id){Rat g,h,t;readpoly(in,g.n);if(g.zero())continue;bool again=true;while(again){again=false;for(auto&x:f){assert(fmpq_mpoly_gcd(h.n,g.n,x.n,ctx));if(fmpq_mpoly_total_degree_si(h.n,ctx)>0){assert(fmpq_mpoly_divides(t.n,g.n,h.n,ctx));fmpq_mpoly_swap(t.n,g.n,ctx);again=true;}}}cout<<id<<" remaining_d_degree "<<fmpq_mpoly_degree_si(g.n,1,ctx)<<" remaining_e_degree "<<fmpq_mpoly_degree_si(g.n,0,ctx)<<'\n';assert(fmpq_mpoly_degree_si(g.n,1,ctx)<=0);}}fmpq_mpoly_ctx_clear(ctx);flint_cleanup();}
